#include "Graphics/Utilities/GeometryBVHStore.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace primal;using namespace primal::graphics;
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
// R4: 成员/局部变量避开 near/far 名字（rpcndr.h 空宏）——far→farT、near→nearHit。
struct Ray {double o[3],d[3],farT;};
// Double slab on expanded/shrunken boxes. Margin is a conservative screening
// band, not a proof of shader floating-point equivalence.
bool slab(const ray_geometry::Node& b,const Ray& r,double margin){double lo=0,hi=r.farT;for(int k=0;k<3;++k){double a=double(b.lo[k])-margin,z=double(b.hi[k])+margin;if(a>z)return false;if(r.d[k]==0){if(r.o[k]<a||r.o[k]>z)return false;}else{double t0=(a-r.o[k])/r.d[k],t1=(z-r.o[k])/r.d[k];lo=std::max(lo,std::min(t0,t1));hi=std::min(hi,std::max(t0,t1));if(lo>hi)return false;}}return true;}
bool contains(const ray_geometry::Node& b,const Ray& r,double margin){for(int k=0;k<3;++k)if(!(r.o[k]>double(b.lo[k])+margin && r.o[k]<double(b.hi[k])-margin))return false;return true;}
bool containsExpanded(const ray_geometry::Node& b,const Ray& r,double margin){for(int k=0;k<3;++k)if(r.o[k]<double(b.lo[k])-margin || r.o[k]>double(b.hi[k])+margin)return false;return true;}
int main(int argc,char** argv){try{
 if(argc==2&&std::string(argv[1])=="--selftest"){ray_geometry::Node b{};for(int k=0;k<3;++k){b.lo[k]=-1;b.hi[k]=1;}Ray x{{0,0,0},{1,0,0},2},y{{2,2,0},{1,0,0},1},z{{-2,1,0},{1,0,0},4};check(contains(b,x,.001)&&slab(b,x,-.001),"inside");check(!slab(b,y,.001),"outside miss");check(!slab(b,z,-.001)&&slab(b,z,.001),"edge uncertain");std::puts("leaf coverage selftest passed");return 0;}
 check(argc==2,"usage: TestEnvironmentLeafCoverage <record-file>");ray_geometry::SceneBVH scene;check(ray_geometry::LoadSceneBVH(".primal-cache/geometry-bvh/5d07eba5b7554607.tlas",6703585667342222855ull,scene),"load PBVH");const auto cert=ray_geometry::CertifyCompactTraversal(scene);check(cert.valid&&cert.top_max_pending<=64&&cert.bottom_max_pending<=64,"complete valid BVH");std::vector<const ray_geometry::Node*> leaves;for(const auto& n:scene.top)if(n.links[3]){check(n.links[3]==1,"TLAS leaf type");leaves.push_back(&n);}check(!leaves.empty(),"nonempty leaves");
 constexpr size_t words=584u*128u;std::ifstream f(argv[1],std::ios::binary|std::ios::ate);check(bool(f)&&f.tellg()==std::streampos(words*sizeof(u32)),"exact record size");f.seekg(0);std::vector<u32> a(words);check(bool(f.read(reinterpret_cast<char*>(a.data()),words*sizeof(u32))),"read records");u64 active=0,queries=0,inside=0,outside=0,originBoundary=0,hit=0,miss=0,segmentBoundary=0,subnormal=0,unknown=0,blocked=0,open=0;
 for(u32 i=0;i<584;++i){u32 base=i*64;check(a[base]==0x454e5650u,"sample stamp");for(u32 lane=0;lane<4;++lane){u32 r=base+16+lane*12,q=584u*96u+i*32u+lane*8u;check(a[r]<=1u,"lane stamp");active+=a[r];bool traversed=a[r+2]!=0||a[r+3]!=0,present=a[q+7]!=0xffffffffu;check(present==traversed,"query stamp versus traversal");if(!present)continue;check(a[r]&&a[q+7]==0xe5710003u,"scalar query stamp");++queries;check(a[r+1u]<=2u,"query outcome");unknown+=a[r+1u]==0u;blocked+=a[r+1u]==1u;open+=a[r+1u]==2u;Ray ray{};bool tiny=false;double scale=1;for(u32 k=0;k<7;++k){float v=std::bit_cast<float>(a[q+k]);check(std::isfinite(v),"nonfinite query");if(std::fpclassify(v)==FP_SUBNORMAL)tiny=true;if(k<3){ray.o[k]=v;scale=std::max(scale,std::abs(double(v)));}else if(k<6)ray.d[k-3]=v;else ray.farT=v;}check(ray.farT>0,"positive far");check(ray.d[0]!=0 || ray.d[1]!=0 || ray.d[2]!=0,"nonzero direction");for(u32 k=0;k<3;++k)scale=std::max(scale,std::abs(ray.o[k]+ray.d[k]*ray.farT));double margin=scale*1e-5;bool in=false,nearHit=false,definiteHit=false,expandedHit=false;for(auto b:leaves){in|=contains(*b,ray,margin);nearHit|=containsExpanded(*b,ray,margin);definiteHit|=slab(*b,ray,-margin);expandedHit|=slab(*b,ray,margin);}if(tiny){++subnormal;++originBoundary;++segmentBoundary;continue;}if(in)++inside;else if(nearHit)++originBoundary;else ++outside;if(definiteHit)++hit;else if(expandedHit)++segmentBoundary;else ++miss;}}
 check(queries&&inside+outside+originBoundary==queries&&hit+miss+segmentBoundary==queries,"positive and exhaustive coverage");std::printf("[ENV_LEAF_COVERAGE] source=%s leaves=%zu active=%llu queries=%llu origin_inside=%llu origin_outside=%llu origin_uncertain=%llu segment_hit=%llu segment_miss=%llu segment_uncertain=%llu subnormal=%llu unknown=%llu blocked=%llu open=%llu margin=1e-5*max(1,abs(origin),abs(endpoint)) gpu_exact_box_equivalence=unproven\n",argv[1],leaves.size(),(unsigned long long)active,(unsigned long long)queries,(unsigned long long)inside,(unsigned long long)outside,(unsigned long long)originBoundary,(unsigned long long)hit,(unsigned long long)miss,(unsigned long long)segmentBoundary,(unsigned long long)subnormal,(unsigned long long)unknown,(unsigned long long)blocked,(unsigned long long)open);return 0;
 }catch(const std::exception& e){std::fprintf(stderr,"[ENV_LEAF_COVERAGE] FAIL %s\n",e.what());return 1;}}
